#!/usr/bin/env python3
# CoAP Flowchart PNG Decoder
# Run: python decode_flowchart.py
import base64, os

os.chdir(os.path.dirname(os.path.abspath(__file__)))

images = {}
images[0] = ""
images[1] = ""
images[2] = ""
images[3] = ""
images[4] = ""
images[5] = ""
images[6] = ""
images[7] = ""

for i, data in images.items():
    fname = "flowchart_" + "01_architecture|02_startup|03_server|04_client|05_firmware_upgrade|06_message_structure|07_interaction_sequence|08_coap_build".split("|")[i] + ".png"
    with open(fname, "wb") as f:
        f.write(base64.b64decode(data))
    print("Saved " + fname)

print("All flowchart images saved!")

